local config = {
  ui_story_31990401_1_dialog_content = "Ayo, saatnya bagi kita untuk keluar.",
  ui_story_31990401_2_dialog_content = "Tidak akan mengunjungi ruang perang hari ini mengacaukan pekerjaanmu, Yingel?",
  ui_story_31990401_3_dialog_content = "Tidak juga, aku libur hari ini.",
  ui_story_31990401_4_dialog_content = "Keren, saya khawatir itu akan mengganggu pekerjaan Anda.",
  ui_story_31990401_5_dialog_content = "Apakah Anda pikir saya gila kerja, PlayerName?",
  ui_story_31990401_6_dialog_content = "Sejujurnya... Ya.",
  ui_story_31990401_7_dialog_content = "Bukan kejutan. Lagipula aku menghabiskan sebagian besar waktu di ruang perang.",
  ui_story_31990401_8_dialog_content = "Itu wajar bagi Anda untuk mendapatkan kesan itu, PlayerName.",
  ui_story_31990401_9_dialog_content = "Namun, bagi saya, bekerja benar-benar merupakan bagian penting untuk membuktikan diri dan nilai saya.",
  ui_story_31990401_10_dialog_content = "Tapi jangan bicara tentang pekerjaan hari ini dan habiskan saja sebagai teman.",
  ui_story_31990401_11_dialog_content = "Tentu!",
  ui_story_31990401_12_dialog_content = "Ini dia.",
  ui_story_31990401_13_dialog_content = "Tunggu, ini hadiah untukmu.",
  ui_story_31990401_14_dialog_content = "Keju?",
  ui_story_31990401_15_dialog_content = "Anda suka produk keju, bukan?",
  ui_story_31990401_16_dialog_content = "Ini adalah keju premium dari Umbraton. Ini cukup enak.",
  ui_story_31990401_17_dialog_content = "Jadi itu yang Anda dapatkan sebelum kami pergi, saya mengerti.",
  ui_story_31990401_18_dialog_content = "Saya tidak berharap Anda mengingat apa yang saya suka... Terima kasih, saya menyukainya.",
  ui_story_31990401_19_dialog_content = "Itulah yang dilakukan teman, mengingat apa yang disukai satu sama lain!",
  ui_story_31990401_20_dialog_content = "Apakah itu sebuah tantangan?",
  ui_story_31990401_21_dialog_content = "Biarkan saya berpikir ... Anda mungkin suka mempelajari hal-hal baru, PlayerName.",
  ui_story_31990401_22_dialog_content = "Meskipun itu tanggung jawab Anda untuk menjaga Colossus, itu juga dianggap sebagai bunga.",
  ui_story_31990401_23_dialog_content = "Sebuah tangan PlayerName suka tidur dengan Kunang-kunang di pelukannya saat masih kecil—",
  ui_story_31990401_24_dialog_content = "Dan…",
  ui_story_31990401_25_dialog_content = "Baiklah baiklah, Yingel, kamu lulus ujian persahabatan!",
  ui_story_31990401_26_dialog_content = "Ayo pergi dan jangan buang waktu lagi di hari libur berharga Anda!",
  ui_story_31990401_27_dialog_content = "(Tolong, jangan lagi tentang masa laluku yang memalukan darimu!)",
  ui_story_31990401_28_dialog_content = "(Betapa salahnya bertanya kepada Petugas Intelijen Illumina tentang diri Anda...)",
  ui_story_31990401_29_dialog_content = "Lewat sini.",
  ui_story_31990401_30_dialog_content = "Ini adalah salah satu kantor saya.",
  ui_story_31990401_31_dialog_content = "Itu tidak memegang lilin ke kamar-kamar di Colossus, tapi terang dan luas menurut standar Illumina.",
  ui_story_31990401_32_dialog_content = "Saya biasanya menangani beberapa urusan resmi di sini, seperti memilah-milah informasi.",
  ui_story_31990401_33_dialog_content = "Setelah mengumpulkan informasi dari seluruh dunia, data harus diatur dan diproses agar berguna.",
  ui_story_31990401_34_dialog_content = "Apakah itu beberapa informasi di dinding?",
  ui_story_31990401_35_dialog_content = "Ya, beberapa pergi ke sana agar mudah dijangkau.",
  ui_story_31990401_36_dialog_content = "Jadi inilah yang Anda lakukan, Yingel...",
  ui_story_31990401_37_dialog_content = "Tidak semuanya, tetapi bagian penting darinya.",
  ui_story_31990401_38_dialog_content = "Apakah tidak membosankan bagimu di sini?",
  ui_story_31990401_39_dialog_content = "Mungkin bisa untuk banyak orang.",
  ui_story_31990401_40_dialog_content = "Tetapi bagi saya, hanya melakukan gerakan itu juga menyenangkan.",
  ui_story_31990401_41_dialog_content = "Kau tahu, kau sangat keren saat mengatakan itu!",
  ui_story_31990401_42_dialog_content = "Saya mengerti mengapa Illumina menginginkan spesialis seperti Anda sekarang.",
  ui_story_31990401_43_dialog_content = "Benar-benar? Ini sebenarnya pertama kalinya saya memiliki pengunjung di sini.",
  ui_story_31990401_44_dialog_content = "Bukan teman untuk tujuan pekerjaan, tetapi hanya teman untuk mengenal lebih baik.",
  ui_story_31990401_45_dialog_content = "Dan saya harus melayani sesuatu untuk itu.",
  ui_story_31990401_46_dialog_content = "Biskuit baik-baik saja dengan Anda?",
  ui_story_31990401_47_dialog_content = "Tentu!",
  ui_story_31990401_48_dialog_content = "Anda mau minum apa, PlayerName?",
  ui_story_31990401_49_dialog_content = "Susu.",
  ui_story_31990401_50_dialog_content = "Anda harus memilikinya di sini, bukan?",
  ui_story_31990401_51_dialog_content = "Apa pun yang Anda punya!",
  ui_story_31990401_52_dialog_content = "Ahem, saya tidak pilih-pilih sama sekali tentang itu.",
  ui_story_31990401_53_dialog_content = "Panggilanmu, Yingel!",
  ui_story_31990401_54_dialog_content = "Oh, ada minuman baru yang ingin Anda coba.",
  ui_story_31990401_55_dialog_content = "Setiap alergi terhadap kedelai, PlayerName?",
  ui_story_31990401_56_dialog_content = "Tidak.",
  ui_story_31990401_57_dialog_content = "Besar. Silakan minum.",
  ui_story_31990401_58_dialog_content = "Apa ini? Rasanya seperti susu tetapi memiliki rasa yang berbeda ...",
  ui_story_31990401_59_dialog_content = "Halus seperti sutra, kaya, dan lebih baik dari susu! Apakah terbuat dari kedelai?",
  ui_story_31990401_60_dialog_content = "Ya. Ini adalah makanan baru yang dikembangkan oleh Illumina.",
  ui_story_31990401_61_dialog_content = "Namanya susu kedelai, minuman yang dipekatkan dari sari kedelai olahan.",
  ui_story_31990401_62_dialog_content = "Ini adalah pertama kalinya saya mendengarnya.",
  ui_story_31990401_63_dialog_content = "Lezat! Satu porsi lagi, tolong!",
  ui_story_31990401_64_dialog_content = "Bukan masalah.",
  ui_story_31990401_65_dialog_content = "Sebenarnya, itu diciptakan untuk mengatasi kekurangan pasokan di militer Illumina.",
  ui_story_31990401_66_dialog_content = "Saya ada hubungannya dengan asalnya juga.",
  ui_story_31990401_67_dialog_content = "Benar-benar? Apa ceritanya?",
  ui_story_31990401_68_dialog_content = "Beberapa bulan yang lalu, saya melihat limbah produk kedelai yang signifikan dalam persediaan kami.",
  ui_story_31990401_69_dialog_content = "Dengan kata lain, para prajurit bosan dengan makanan kedelai yang telah lama kami sajikan.",
  ui_story_31990401_70_dialog_content = "Produk kedelai telah menjadi bahan pokok pengeluaran militer Illumina, mengambil sebagian besar pasokan makanan.",
  ui_story_31990401_71_dialog_content = "Meskipun ketidaksukaan itu bisa dimengerti, kita tidak bisa terus membuang-buang uang.",
  ui_story_31990401_72_dialog_content = "Belum lagi kedelai bergizi dan sumber energi yang baik...",
  ui_story_31990401_73_dialog_content = "Bagaimanapun, kami harus menemukan cara baru agar semua orang menerima kacang kecil itu lagi.",
  ui_story_31990401_74_dialog_content = "Itu nama panggilan yang cukup menawan ...",
  ui_story_31990401_75_dialog_content = "Heheh, saya memang suka produk kedelai.",
  ui_story_31990401_76_dialog_content = "Bukankah kacang-kacangan itu terlihat seperti tentara di lapangan saat Anda meletakkannya di atas meja satu per satu?",
  ui_story_31990401_77_dialog_content = "Mereka terus mengisi daya sampai mengisi perut kita.",
  ui_story_31990401_78_dialog_content = "Sekarang Anda mengatakannya seperti itu, ya, itu terdengar seperti garis pertempuran.",
  ui_story_31990401_79_dialog_content = "Jadi, bagaimana Anda mendapatkan ide tentang susu kedelai yang begitu enak?",
  ui_story_31990401_80_dialog_content = "Itu adalah proses yang agak rumit.",
  ui_story_31990401_81_dialog_content = "Saya dapat meninjau data dan merencanakan dengan baik.",
  ui_story_31990401_82_dialog_content = "Tetapi saya membutuhkan seseorang yang profesional untuk menangani pekerjaan studi.",
  ui_story_31990401_83_dialog_content = "Jadi saya menemukan Migard untuk R&D.",
  ui_story_31990401_84_dialog_content = "Apa itu Migard?",
  ui_story_31990401_85_dialog_content = "(Yingel pasti mengalami kesulitan... Tunggu, mungkin itu Migard siapa yang di bawah jempol?)",
  ui_story_31990401_86_dialog_content = "Ya, dia sangat patuh.",
  ui_story_31990401_87_dialog_content = "Dia menerima tugas itu dengan gembira dan menyelesaikannya sesuai jadwal.",
  ui_story_31990401_88_dialog_content = "<color=#e8d9bb>Tiga bulan yang lalu...</color>",
  ui_story_31990401_89_dialog_content = "Anda tahu gambaran besarnya. Sekarang kita beralih ke penelitian makanan baru.",
  ui_story_31990401_90_dialog_content = "Makanan baru? Kedengarannya cukup menarik.",
  ui_story_31990401_91_dialog_content = "Saya sedang mengerjakan proyek lain sekarang dan mungkin perlu mengubah jadwal saya.",
  ui_story_31990401_92_dialog_content = "Tapi sampai saat itu, saya ingin mengenal Nona yang lebih menarik Yingel diri...",
  ui_story_31990401_93_dialog_content = "Ketua Reinhardt mengatakan jadwal apa pun dapat diatur ulang.",
  ui_story_31990401_94_dialog_content = "\"Beritahu saya jika Migard melakukan sesuatu yang aneh\" adalah kata-kata persisnya.",
  ui_story_31990401_95_dialog_content = "Baik, baik... Kenapa kau harus begitu kaku!",
  ui_story_31990401_96_dialog_content = "Saya akan menangani penelitiannya, tetapi Anda harus lebih banyak tersenyum dengan wajah cantik seperti itu.",
  ui_story_31990401_97_dialog_content = "Saya menghargai usaha, Migard.",
  ui_story_31990401_98_dialog_content = "Tua yang sama Migard, Jadi begitu.",
  ui_story_31990401_99_dialog_content = "Kombinasi minuman kedelai dan susu mendapat persetujuan populer.",
  ui_story_31990401_100_dialog_content = "Banyak orang bahkan mengira itu adalah spesialisasi asing baru dan langsung bertanya kepada staf akuisisi.",
  ui_story_31990401_101_dialog_content = "Merekayasa ulang kacang kecil telah sukses!",
  ui_story_31990401_102_dialog_content = "Sekarang, kita bisa mengakhiri pemborosan produk kedelai, dan...",
  ui_story_31990401_103_dialog_content = "Kita bisa menikmati minuman yang luar biasa.",
  ui_story_31990401_104_dialog_content = "Jadi bagaimana susu kedelai dibuat?",
  ui_story_31990401_105_dialog_content = "Pekerjaan sebenarnya tidak sulit. Hanya saja peralatan bisa menjadi masalah.",
  ui_story_31990401_106_dialog_content = "Kami membuat mixer sentrifugal berkecepatan tinggi raksasa di Undercity.",
  ui_story_31990401_107_dialog_content = "Cukup tambahkan kedelai dan air, tunggu sebentar, dan kita akan mendapatkan susu kedelai.",
  ui_story_31990401_108_dialog_content = "Mesin diotomatiskan untuk melakukan setiap langkah, sehingga kami dapat memproduksi secara massal setiap kali habis.",
  ui_story_31990401_109_dialog_content = "Kami hanya memiliki satu mesin saat ini, tapi Migard mengklaim itu cukup untuk seluruh pasukan.",
  ui_story_31990401_110_dialog_content = "Harus saya akui bahwa Anda adalah pemikir yang brilian untuk menghasilkan ide, Yingel...",
  ui_story_31990401_111_dialog_content = "Sayangnya, saya kira saya tidak akan berhasil di atas Colossus.",
  ui_story_31990401_112_dialog_content = "Mesin itu adalah milik Illumina dan ukurannya sangat besar.",
  ui_story_31990401_113_dialog_content = "Plus, saya tidak berwenang bagi Anda untuk mengambilnya saat ini, maaf ...",
  ui_story_31990401_114_dialog_content = "Tapi jangan ragu untuk datang menemui saya di sini kapan saja Anda ingin susu kedelai.",
  ui_story_31990401_115_dialog_content = "Siapa tahu ada makanan baru berbasis teknologi Illumina yang bisa kamu coba.",
  ui_story_31990401_116_dialog_content = "Tentu!",
  ui_story_31990601_1_dialog_content = "Log Ekologi Rediesel Wrench, Hari 2.",
  ui_story_31990601_2_dialog_content = "Pak itu pergi mencari makanan lagi...",
  ui_story_31990601_3_dialog_content = "Sejak anggota tertentu dari kelompok mereka secara tidak sengaja meledakkan kantin...",
  ui_story_31990601_4_dialog_content = "Seluruh Rediesel Wrench harus melakukan ekspedisi berburu secara rutin seperti ini...",
  ui_story_31990601_5_dialog_content = "Hari ini, tanda mereka tidak lain adalah...",
  ui_story_31990601_6_dialog_content = "Spesimen langka dan berair yang dikenal sebagai PlayerName, yang sedang berusaha keras untuk melarikan diri dari gurun.",
  ui_story_31990601_7_option_content = "…?",
  ui_story_31990601_8_dialog_content = "Tampaknya dia telah berhasil melarikan diri dari Rediesel Wrench yang rakus—sungguh prestasi yang luar biasa.",
  ui_story_31990601_9_dialog_content = "Apa? T-Tidak, aku hanya di sini untuk sebuah pekerjaan...",
  ui_story_31990601_10_dialog_content = "Aku rasa aku baru saja mendengar suara... Sepertinya ada orang yang sedang merekam dokumenter alam, jadi aku datang untuk melihat.",
  ui_story_31990601_11_dialog_content = "Aku tidak berharap menemukanmu di sini, Yingel... Apa yang sedang kamu lakukan?",
  ui_story_31990601_12_dialog_content = "Seperti yang bisa kamu lihat, saya sedang mengamati Rediesel Wrench di habitat alaminya.",
  ui_story_31990601_13_dialog_content = "Habitat alami? Tapi itu hanya tempat mereka tinggal, bukan?",
  ui_story_31990601_14_dialog_content = "Tepatnya, yang membuatnya menjadi habitat mereka. Adapun cara hidup mereka... Saya percaya \"alami\" juga merupakan cara yang sempurna untuk menggambarkannya.",
  ui_story_31990601_15_dialog_content = "Pola hidup mereka mungkin dapat memberi kita gambaran tentang kehidupan nenek moyang Aurorian primitif kita.",
  ui_story_31990601_16_dialog_content = "Itu sedikit berlebihan...",
  ui_story_31990601_17_dialog_content = "Tunggu... Kamu tidak berencana melakukan sesuatu yang buruk pada kamp mereka, kan?!",
  ui_story_31990601_18_dialog_content = "...",
  ui_story_31990601_19_dialog_content = "Apakah saya benar-benar orang seperti itu di matamu, PlayerName?",
  ui_story_31990601_20_dialog_content = "Rediesel Wrench mungkin kurang struktur dan disiplin, tetapi itu tidak membuat mereka menjadi Eclipsite. Oleh karena itu, saya tidak punya alasan untuk mengarahkan senjata saya pada mereka.",
  ui_story_31990601_21_dialog_content = "J-Jadi... Kenapa sebenarnya kamu di sini?",
  ui_story_31990601_22_dialog_content = "Aku tidak berbohong padamu. Aku benar-benar sedang menjalankan misi observasi... Aku hanya sedikit menyimpang saja.",
  ui_story_31990601_23_dialog_content = "Awalnya, saya berniat untuk menyurvei area antara garis depan dan gurun, tapi kemudian saya berakhir di dekat kamp Rediesel Wrench tanpa menyadarinya.",
  ui_story_31990601_24_dialog_content = "Aku tidak berencana untuk tinggal lama, tetapi Rediesel Desert tampaknya memiliki daya tarik tertentu...",
  ui_story_31990601_25_dialog_content = "Saya mengemudi selama dua hari, berusaha pergi, hanya untuk menemukan diri saya tepat di tempat saya memulai.",
  ui_story_31990601_26_dialog_content = "...",
  ui_story_31990601_27_dialog_content = "Itu hanya terdengar seperti kamu tersesat!!!",
  ui_story_31990601_28_dialog_content = "Saya tidak tersesat. Saya hanya sedang menjalankan Rencana Darurat #43, itu saja.",
  ui_story_31990601_29_dialog_content = "Apa kamu yakin kamu tidak hanya mengarang itu?!",
  ui_story_31990601_30_dialog_content = "Sama sekali tidak. Malah, ini adalah solusi optimal, mengingat seorang elf gurun telah membawakan saya makanan selama ini.",
  ui_story_31990601_31_dialog_content = "Dengan bantuannya, saya bisa menjalankan Rencana Darurat #43 tanpa khawatir tentang batasan waktu.",
  ui_story_31990601_32_dialog_content = "Tunggu, tunggu, tunggu!",
  ui_story_31990601_33_dialog_content = "Apa itu elf gurun?!",
  ui_story_31990601_34_dialog_content = "Seorang makhluk yang baik dan berbudi pekerti dalam bentuk gadis muda. Jelas, dia harus tinggal dengan Rediesel Wrench karena kebutuhan.",
  ui_story_31990601_35_dialog_content = "Jadi itu berarti...",
  ui_story_31990601_36_dialog_content = "Kamu hanya bisa bertahan di sini karena kamu telah memanfaatkan persediaan makanan Rediesel Wrench!",
  ui_story_31990601_37_dialog_content = "Seperti yang saya katakan, mereka adalah hadiah dari elf gurun dan bukan dari Rediesel...",
  ui_story_31990601_38_dialog_content = "Itu dia, Bu Wajah Tanpa Ekspresi!",
  ui_story_31990601_39_dialog_content = "Itu…?",
  ui_story_31990601_40_dialog_content = "Hei, PlayerName! Apa yang kamu lakukan di sini? Apakah kamu juga sedang berkelana melalui gurun?",
  ui_story_31990601_41_dialog_content = "Itu…",
  ui_story_31990601_42_dialog_content = "(Tunggu sebentar! Dari cara pandangnya, Yingel masih belum tahu bahwa dia adik perempuan Sinsa...)",
  ui_story_31990601_43_dialog_content = "(Dan karena Yingel tidak memakai seragamnya... Eve pasti mengira dia hanya pelancong biasa!)",
  ui_story_31990601_44_dialog_content = "(Jika saya ingin menjaga segalanya tetap terkendali, saya tidak boleh membiarkan mereka mengetahui identitas asli satu sama lain!)",
  ui_story_31990601_45_dialog_content = "Er... Ya, itu benar! Saya sebenarnya sedang bepergian dengan Nona Pokerface di sini!",
  ui_story_31990601_46_dialog_content = "Seperti yang saya katakan sebelumnya, saya bukanlah seorang pelancong. Gurun Rediesel adalah rumah saya.",
  ui_story_31990601_47_dialog_content = "Oh, aku sangat senang Rediesel Desert membuatmu merasa seperti di rumah sendiri, Miss Pokerface!",
  ui_story_31990601_48_dialog_content = "Jika itu masalahnya, maka kamu akan menyukai makan siang hari ini! Ta-da!",
  ui_story_31990601_49_dialog_content = "Kadal lada hantu ekstra pedas!",
  ui_story_31990601_50_dialog_content = "Itu dia... Alasan sebenarnya mengapa setiap orang menjauhi Rediesel Desert!",
  ui_story_31990601_51_dialog_content = "<size=30>Apakah ini... benar-benar dimaksudkan untuk dimakan? Seperti yang kukira, tempat ini patut ditakuti... Tapi...</size>",
  ui_story_31990601_52_dialog_content = "Terima kasih. Sebagai orang asli dari Gurun Rediesel, saya tentu saja menyukai makanan khas lokal ini.",
  ui_story_31990601_53_dialog_content = "Hadiahmu sangat dihargai. Aku tak sabar ingin mencicipi hidangan menakjubkan ini.",
  ui_story_31990601_54_dialog_content = "Ayo lanjutkan! Aku bahkan membawa lebih banyak lagi, jika kamu masih lapar setelahnya!",
  ui_story_31990601_55_dialog_content = "S... Saya rasa satu saja sudah lebih dari cukup.",
  ui_story_31990601_56_dialog_content = "Um... Jika kamu tidak yakin bagaimana cara memakannya, aku bisa memberimu beberapa petunjuk...",
  ui_story_31990601_57_dialog_content = "Tentu saja, saya tahu cara memakan ini. Seperti yang saya katakan, saya adalah penduduk asli dari Gurun Rediesel.",
  ui_story_31990601_58_dialog_content = "Glek!",
  ui_story_31990601_59_dialog_content = "Wow, kamu memakan semuanya dalam satu gigitan! Tidak banyak orang yang bisa melakukan itu di sini!",
  ui_story_31990601_60_dialog_content = "Kamu bisa saja dianggap sebagai penduduk asli Rediesel, Miss Pokerface!",
  ui_story_31990601_61_dialog_content = "T-Tunggu sebentar... Kamu benar-benar tidak perlu sampai sejauh ini... Ludahkan saja jika itu terlalu banyak...",
  ui_story_31990601_62_dialog_content = "<size=30>Dia tidak tahu siapa kamu, jadi berhenti berpura-pura sekarang ...</size>",
  ui_story_31990601_63_dialog_content = "Tolong berhenti bicara. Saya sedang mencoba menikmati makanan lezat saya...",
  ui_story_31990601_64_dialog_content = "Mmm, lezat... Urk!",
  ui_story_31990601_65_dialog_content = "Apa sebuah kenikmatan kuliner... Blegh!",
  ui_story_31990601_66_dialog_content = "M-Maaf... Tapi wajahmu sekarang merah semua!",
  ui_story_31990601_67_dialog_content = "Itu hanya karena makanannya sangat enak... Hrrng!",
  ui_story_31990601_68_dialog_content = "L-Lalu kenapa wajahmu mulai berubah menjadi hijau?!",
  ui_story_31990601_69_dialog_content = "Itu-Itu hanya cara saya berterima kasih kepada alam atas makanan lezat ini... Urgh!",
  ui_story_31990601_70_dialog_content = "Ludahkan saja, aku mohon! Mata kamu mulai berair sekarang!",
  ui_story_31990601_71_dialog_content = "Aku tak mungkin membuang sesuatu yang begitu lezat... Yeugh!",
